-- =============================================================
-- supermarkt.sql  ·  SQL Werkplaats, hoofdstuk 10
-- Kassabonnen van twee AH to Go-winkels, januari t/m juni 2023 (fictief).
-- Voer dit bestand uit als één script. Duurt een paar seconden.
-- LET OP: bestaat 'supermarkt' al, dan wordt hij eerst verwijderd.
-- =============================================================
DROP DATABASE IF EXISTS supermarkt;

CREATE DATABASE supermarkt;

USE supermarkt;

CREATE TABLE klanten (
    klant_id   INT PRIMARY KEY,
    voornaam   VARCHAR(50),
    achternaam VARCHAR(50),
    adres      VARCHAR(100),
    woonplaats VARCHAR(50),
    geb_datum  DATE
);

CREATE TABLE producten (
    product_id   INT PRIMARY KEY,
    naam         VARCHAR(100),
    merk         VARCHAR(50),
    categorie    VARCHAR(50),
    verkoopprijs DECIMAL(5,2),
    inkoopprijs  DECIMAL(5,2),
    leverancier  VARCHAR(50)
);

CREATE TABLE medewerkers (
    mdw_id     INT PRIMARY KEY,
    voornaam   VARCHAR(50),
    achternaam VARCHAR(50)
);

CREATE TABLE locatie (
    loc_id INT PRIMARY KEY,
    naam   VARCHAR(100),
    plaats VARCHAR(50)
);

CREATE TABLE transactie (
    trans_id INT PRIMARY KEY,
    datum    DATE,
    klant_id INT,
    medew_id INT,
    loc_id   INT,
    FOREIGN KEY (klant_id) REFERENCES klanten(klant_id),
    FOREIGN KEY (medew_id) REFERENCES medewerkers(mdw_id),
    FOREIGN KEY (loc_id)   REFERENCES locatie(loc_id)
);

CREATE TABLE trans_prod (
    trans_id INT,
    prod_id  INT,
    aantal   INT,
    PRIMARY KEY (trans_id, prod_id),
    FOREIGN KEY (trans_id) REFERENCES transactie(trans_id),
    FOREIGN KEY (prod_id)  REFERENCES producten(product_id)
);

-- Eerst de ouders, dan de kinderen: een foreign key kan alleen
-- verwijzen naar een rij die al bestaat.

